cd /home/sauyon/.claude/projects && python3 -c "
import json,glob,collections
c=collections.Counter(); ent=collections.Counter(); orig=collections.Counter()
for f in glob.glob('**/*.jsonl',recursive=True)[:400]:
    try:
        for l in open(f,errors='replace'):
            try: d=json.loads(l)
            except: continue
            if d.get('type')!='user' or 'toolUseResult' in d: continue
            c[d.get('promptSource')]+=1; ent[d.get('entrypoint')]+=1; orig[str(d.get('origin'))[:30]]+=1
    except: pass
print('promptSource',c.most_common()); print('entrypoint',ent.most_common()); print('origin',orig.most_common(10))
"
